# 1. Invert the flow: post-hoc claim checking fails; force generation onto pre-cleared claim graphs
def govern_campaign(draft_prompt, claim_kb, compliance_rules):
    # Deconstruct generation into atomic claims rather than evaluating holistic copy
    atomic_assertions = extract_verifiable_propositions(draft_prompt)

    # 2. Reject fuzzy semantic search; require strict formal entailment against canonical proof
    unbacked_claims = [c for c in atomic_assertions if not provable_by_entailment(c, claim_kb)]

    # 3. Any novel assertion forces a human-in-the-loop triage with isolated diffs
    if unbacked_claims or contains_restricted_lexicon(draft_prompt, compliance_rules):
        return route_to_human_reviewer(draft_prompt, focus_diff=unbacked_claims)

    # 4. Assume downstream ad pipes strip C2PA metadata; enforce baked-in manifest/watermarks
    rendered_creative = bake_pixel_and_lexical_disclosure(draft_prompt, compliance_rules.jurisdiction)

    # 5. Only route to auto-publish if draft is a pure permutation of pre-audited components
    return publish(rendered_creative) if compliance_rules.tier == 'low_risk' else route_to_human_reviewer(rendered_creative)
